# *args
def total(*numbers):
    return sum(numbers)

print(total(1, 2, 3, 4))  # 10

# **kwargs
def create_profile(**info):
    for key, value in info.items():
        print(f'{key}: {value}')

create_profile(name='Alice', age=30, city='NYC')

# Combining
def log(message, *tags, **metadata):
    print(f'[{message}] tags={tags} meta={metadata}')

log('Error', 'critical', 'auth', user='alice', code=403)

# Unpacking
coords = [1, 2, 3]
print(max(*coords))  # same as max(1, 2, 3)
